def simulate_boost(V_in, D, L, C, R, f_sw, periods=1500, steps=200):
    """Simulate an ideal boost converter (ideal switch and diode) from rest.

    V_in: input voltage; D: duty cycle; L, C: inductor and output capacitor; R: load resistance;
    f_sw: switching frequency; periods: how many switching periods to simulate;
    steps: time steps per period. Return (average output voltage, peak-to-peak output ripple),
    both measured over the last 20 periods.
    """
    raise NotImplementedError

exercises.reference:
def simulate_boost(V_in, D, L, C, R, f_sw, periods=1500, steps=200):
    dt = 1 / (f_sw * steps)
    on_steps = round(D * steps)
    i_L = 0.0
    v_C = V_in                        # the output capacitor charges to V_in through the diode at once
    out = []
    for p in range(periods):
        for s in range(steps):
            if s < on_steps:          # switch on: inductor across the input; diode blocks
                i_L += dt * V_in / L
                i_C = -v_C / R
            else:                     # switch off: inductor current flows through the diode
                i_L += dt * (V_in - v_C) / L
                if i_L < 0:
                    i_L = 0.0
                i_C = i_L - v_C / R
            v_C += dt * i_C / C
            if p >= periods - 20:
                out.append(v_C)
    return sum(out) / len(out), max(out) - min(out)
